presetAutojoinGuard.impl:
// Added inside apply(ctx) at packages/data/preset-autojoin/src/index.ts:147-162,
// alongside the existing fire-and-forget agent/created listener (:149-161).
//
// Also extend the AutojoinPresetService structural interface (:50-72) with an
// OPTIONAL member so unit-test mocks can stub it:
//   pendingSwitch?(sessionId: string): Promise<unknown> | undefined
// (The real AgentPresets satisfies it once the accessor at agent-presets/:706 lands.)

export function apply(ctx: Context): void {
  const listener = createAutojoinListener(ctx.agentPresets)
  ctx.on('agent/created', (event) => {
    void listener(event).catch((err: unknown) => { void err })
  })
  // da §4.2 pre-step guard: await any in-flight preset switch before the
  // turn's first step assembles, so a select racing the first prompt cannot
  // leave scope observers observing a torn parent chain. Restores the deleted
  // apiproxy turn-path `await pendingSwitch` (api-proxy.ts:2397, removed by
  // upstream 4f00a8b) in the data-agent layer. agent/pre-step is an AWAITED
  // middleware (unlike agent/created, which preset-autojoin:14-21 documents
  // as fire-and-forget — framework does not await listeners), so this await
  // is guaranteed to block the step pipeline. No-op once the switch settles:
  // pendingSwitch returns undefined (switches entry deleted in select's
  // finally at agent-presets:704), so latency is added only when a select is
  // genuinely in-flight. Past the first turn, swap throws agent-preset/locked
  // (agent-presets:715-722), so no new switch can start — the guard is
  // naturally first-turn-scoped. 10 production agent/pre-step listeners
  // already coexist and chain via next() (compaction:148, agent-instructions:313,
  // session-reference:135, time-context:180, tmux-context:236, phase-gate:985,
  // tool-cordis:384, goal-round-driver:361, repeat-tool-reminder:229,
  // hooks-claude-code:218); this is an 11th, consistent with the architecture.
  ctx.on('agent/pre-step', async ({ agent }, next): Promise<PreStepDecision> => {
    const pending = ctx.agentPresets.pendingSwitch?.(agent.id)
    if (pending !== undefined) await pending
    return next()
  })
}

scopeObserverHardening.impl:
// Added to packages/core/scope/src/index.ts. scopeParents IS a WeakMap
// (verified at :39: `const scopeParents = new WeakMap<ScopeKey, ScopeKey>()`).
// linkScopeParent (:54-58) does `scopeParents.set(key, parent)` (:58) and is
// called by BOTH bindScopeParent (:72-82) and the rebind method (:78-80) on
// the ScopeParentBinding — so `binding.rebind()` (agent-presets:661, inside
// recompose) is a synchronous WeakMap write with zero side effects / no
// disposal (confirms B-DA1 Hypothesis-A refutation: recompose does NOT
// cancel the agent). scopeChainOf (:98-102) and scopeParentOf (:89-91) both
// walk scopeParents.get(cursor); scopeChainOf returns a fresh array, but a
// caller that does scopeParentOf→await→scopeParentOf, or reads the chain,
// awaits, then re-reads, IS torn by a mid-flight rebind. The snapshot helper
// detaches the read from later rebind writes.

/**
 * A frozen snapshot of {@link scopeChainOf}, safe to hold across an await.
 * The returned readonly array is a copy detached from later `rebind` writes
 * (`binding.rebind()` → `linkScopeParent` → `scopeParents.set`), so an
 * observer that reads the chain, awaits, and re-reads is not torn by a
 * mid-flight preset switch. Prefer this over a raw `scopeParentOf`→await→
 * `scopeParentOf` sequence, or a `scopeChainOf` call inside an await loop,
 * in any observer whose parent-chain read spans an await.
 * @param key - the starting key, or `undefined` for the empty chain.
 * @returns a frozen nearest-first key array `[key, parent, …]`.
 */
export function scopeChainSnapshotOf(key: ScopeKey | undefined): readonly ScopeKey[] {
  return Object.freeze(scopeChainOf(key))
}
